right:
@import 'c/ihStyles';

:host {
    padding-bottom: 0.75rem; /* space below the card on the record page */
}

.ih-tiles {
    grid-template-columns: repeat(3, minmax(0, 1fr));
}
.ih-tile {
    padding: 8px 12px 8px 16px;
}
.ih-tile-value {
    font-size: 18px;
}
.list {
    list-style: none;
    margin: 0;
    padding: 0;
}
.item {
    padding: 10px 16px;
    border-top: 1px solid var(--ih-line-2);
    display: flex;
    flex-direction: column;
    gap: 4px;
}
.line1 {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
}
.line2 {
    overflow-wrap: anywhere;
}
.ih-note {
    max-width: none;
    font-size: 12px;
}
.ih-card-foot {
    margin: 0;
}
